// verify: every maximal run of \p{Nd} codepoints has length divisible by 10
const re=/\p{Nd}/u; let runs=[],start=-1;
for(let c=0;c<=0x10FFFF;c++){
  if(c>=0xD800&&c<=0xDFFF){ if(start>=0){runs.push([start,c-1]);start=-1;} continue;}
  const isNd=re.test(String.fromCodePoint(c));
  if(isNd&&start<0)start=c;
  if(!isNd&&start>=0){runs.push([start,c-1]);start=-1;}
}
if(start>=0)runs.push([start,0x10FFFF]);
let bad=runs.filter(r=>(r[1]-r[0]+1)%10!==0);
console.log("total runs:",runs.length,"bad runs:",JSON.stringify(bad));
console.log("blocks:",runs.reduce((a,r)=>a+(r[1]-r[0]+1)/10,0));
'

