/**
 * Unicode tables needed to mirror CPython's string semantics.
 *
 * Nothing here is derived from CPython source: the ranges were produced by
 * enumerating the code point space with V8's own `\p{...}` property escapes,
 * so they describe the same Unicode database the runtime already ships.
 */

/**
 * Maximal runs of General_Category=Nd (decimal digit) code points.
 *
 * Every such run has a length that is a multiple of ten, and each aligned
 * group of ten inside a run starts at that script's "digit zero". That makes
 * `(cp - runStart) % 10` the digit's numeric value without a per-script table.
 */
const ND_RUNS = [
  [48, 57], [1632, 1641], [1776, 1785], [1984, 1993], [2406, 2415],
  [2534, 2543], [2662, 2671], [2790, 2799], [2918, 2927], [3046, 3055],
  [3174, 3183], [3302, 3311], [3430, 3439], [3558, 3567], [3664, 3673],
  [3792, 3801], [3872, 3881], [4160, 4169], [4240, 4249], [6112, 6121],
  [6160, 6169], [6470, 6479], [6608, 6617], [6784, 6793], [6800, 6809],
  [6992, 7001], [7088, 7097], [7232, 7241], [7248, 7257], [42528, 42537],
  [43216, 43225], [43264, 43273], [43472, 43481], [43504, 43513],
  [43600, 43609], [44016, 44025], [65296, 65305], [66720, 66729],
  [68912, 68921], [69734, 69743], [69872, 69881], [69942, 69951],
  [70096, 70105], [70384, 70393], [70736, 70745], [70864, 70873],
  [71248, 71257], [71360, 71369], [71472, 71481], [71904, 71913],
  [72016, 72025], [72784, 72793], [73040, 73049], [73120, 73129],
  [73552, 73561], [92768, 92777], [92864, 92873], [93008, 93017],
  [120782, 120831], [123200, 123209], [123632, 123641], [124144, 124153],
  [125264, 125273], [130032, 130041],
];

/**
 * Code points for which CPython's `Py_UNICODE_ISSPACE` is true but which are
 * outside ASCII. `_PyUnicode_TransformDecimalAndSpaceToASCII` rewrites exactly
 * these to U+0020 before the integer scanner runs, which is why `int('\xa05')`
 * succeeds while `int('\x1c5')` does not.
 */
const NON_ASCII_SPACE = [
  0x85, 0xa0, 0x1680, 0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005,
  0x2006, 0x2007, 0x2008, 0x2009, 0x200a, 0x2028, 0x2029, 0x202f, 0x205f,
  0x3000,
];

/** Whitespace accepted by CPython's C-level `Py_ISSPACE` (ASCII only). */
const ASCII_SPACE = [0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x20];

/** Categories CPython's `str.isprintable()` treats as non-printable. */
const NON_PRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;

/** Numeric value of a decimal-digit code point, or -1 if it is not Nd. */
export function decimalDigitValue(cp) {
  for (let i = 0; i < ND_RUNS.length; i += 1) {
    const [lo, hi] = ND_RUNS[i];
    if (cp < lo) return -1;
    if (cp <= hi) return (cp - lo) % 10;
  }
  return -1;
}

/** True for the ASCII whitespace CPython's integer scanner skips directly. */
export function isAsciiSpace(cp) {
  return ASCII_SPACE.indexOf(cp) !== -1;
}

/** True for non-ASCII code points normalised to a space before scanning. */
export function isTransformedSpace(cp) {
  return NON_ASCII_SPACE.indexOf(cp) !== -1;
}

/** Mirror of CPython `str.isprintable()` for a single code point. */
export function isPrintableCodePoint(cp) {
  if (cp === 0x20) return true;
  return !NON_PRINTABLE.test(String.fromCodePoint(cp));
}

