/**
 * Python exception shapes.
 *
 * `qualifiedName` is what a traceback prints before the colon: bare for
 * builtins (`KeyError`), module-qualified for library exceptions
 * (`bidict.ValueDuplicationError`). `displayMessage()` is `str(exc)`.
 */

export class PyException extends Error {
  constructor(qualifiedName, message) {
    super(`${qualifiedName}: ${message}`);
    this.qualifiedName = qualifiedName;
    this.pyMessage = message;
  }

  displayMessage() {
    return this.pyMessage;
  }
}

/** `ValueError` — raised by the `int()` conversion on malformed input. */
export class PyValueError extends PyException {
  constructor(message) {
    super('ValueError', message);
  }
}

/**
 * `KeyError`. Its `str()` is the *repr* of the missing key rather than the key
 * itself, so `b.inv[5]` reports `KeyError: 5` and `b['a']` reports
 * `KeyError: 'a'`.
 */
export class PyKeyError extends PyException {
  constructor(keyRepr) {
    super('KeyError', keyRepr);
  }
}

/** True when `err` came from emulated Python code rather than a JS bug. */
export function isPyException(err) {
  return err instanceof PyException;
}

