/**
 * CPython `repr()` for the value shapes this program prints.
 *
 * Python values are modelled as: `str` -> JS string, `int` -> JS bigint,
 * `tuple` -> `PyTuple`. Keeping bigint for every integer means `repr()` is a
 * plain decimal rendering with no precision ceiling, matching Python.
 */

import { isPrintableCodePoint } from './unicode-data.mjs';

/** A Python tuple, needed because `KeyAndValueDuplicationError` carries one. */
export class PyTuple {
  constructor(items) {
    this.items = items;
  }
}

function hexEscape(cp) {
  if (cp < 0x100) return `\\x${cp.toString(16).padStart(2, '0')}`;
  if (cp < 0x10000) return `\\u${cp.toString(16).padStart(4, '0')}`;
  return `\\U${cp.toString(16).padStart(8, '0')}`;
}

/**
 * `repr()` of a Python `str`.
 *
 * Single quotes are preferred; CPython switches to double quotes only when the
 * string contains an apostrophe and no double quote, so that no escaping is
 * needed. The chosen quote and the backslash are escaped, `\t`/`\n`/`\r` get
 * short forms, and anything `str.isprintable()` rejects becomes a numeric
 * escape. Printable non-ASCII text (CJK, emoji, ...) is emitted verbatim.
 */
export function reprStr(value) {
  const quote = value.includes("'") && !value.includes('"') ? '"' : "'";

  let out = quote;
  for (const ch of value) {
    const cp = ch.codePointAt(0);
    if (ch === quote || ch === '\\') {
      out += `\\${ch}`;
    } else if (ch === '\t') {
      out += '\\t';
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (cp < 0x20 || cp === 0x7f) {
      out += hexEscape(cp);
    } else if (cp < 0x7f) {
      out += ch;
    } else if (isPrintableCodePoint(cp)) {
      out += ch;
    } else {
      out += hexEscape(cp);
    }
  }
  return out + quote;
}

/** `repr()` of a Python `int`. */
export function reprInt(value) {
  return value.toString();
}

/** `repr()` of any modelled Python value. */
export function pyRepr(value) {
  if (typeof value === 'string') return reprStr(value);
  if (typeof value === 'bigint') return reprInt(value);
  if (value instanceof PyTuple) {
    if (value.items.length === 1) return `(${pyRepr(value.items[0])},)`;
    return `(${value.items.map(pyRepr).join(', ')})`;
  }
  throw new TypeError(`no repr defined for ${typeof value}`);
}

/**
 * `str()` of a modelled Python value.
 *
 * Differs from `repr()` only for `str` itself, where `str()` is the identity.
 * Containers still render their *elements* with `repr()`, which is why
 * `str(('new', 999))` is `('new', 999)`.
 */
export function pyStrOf(value) {
  if (typeof value === 'string') return value;
  return pyRepr(value);
}

/** `repr()` of a Python `dict`, given its items in insertion order. */
export function reprDict(items) {
  const body = items.map(([key, val]) => `${pyRepr(key)}: ${pyRepr(val)}`);
  return `{${body.join(', ')}}`;
}

