  return pyRepr(value);
}

/** `repr()` of a Python `dict`, given its items in insertion order. */
export function reprDict(items) {
  const body = items.map(([key, val]) => `${pyRepr(key)}: ${pyRepr(val)}`);
  return `{${body.join(', ')}}`;
}

