/**
 * Process-level services the emulated script needs from `sys`/`os`.
 *
 * Writes go through `fs.writeSync` rather than `process.stdout.write` so that
 * output is already on the file descriptor before `process.exit()` runs — the
 * stream API buffers asynchronously on pipes and would otherwise drop the tail
 * of a report on the non-zero exit paths.
 */

import { writeSync } from 'node:fs';

const STDOUT_FD = 1;
const STDERR_FD = 2;

function writeAll(fd, text) {
  const buf = Buffer.from(text, 'utf8');
  let offset = 0;
  while (offset < buf.length) {
    offset += writeSync(fd, buf, offset, buf.length - offset);
  }
}

/** Python's `print(value)` — the value plus a trailing newline. */
export function print(text = '') {
  writeAll(STDOUT_FD, `${text}\n`);
}

/** Raw write to stdout, no newline added. */
export function writeStdout(text) {
  writeAll(STDOUT_FD, text);
}

/** Raw write to stderr, no newline added. */
export function writeStderr(text) {
  writeAll(STDERR_FD, text);
}

/**
 * `shutil.get_terminal_size().columns`.
 *
 * `COLUMNS` wins when it is a positive integer; otherwise the real terminal is
 * queried, and a redirected stream falls back to 80.
 */
export function terminalColumns() {
  const env = process.env.COLUMNS;
  if (env !== undefined && /^\s*[-+]?\d+\s*$/.test(env)) {
    const columns = Number.parseInt(env, 10);
    if (columns > 0) return columns;
  }
  return process.stdout.columns || 80;
}

/** `sys.argv[1:]` — the argument words argparse is handed by default. */
export function argvTail() {
  return process.argv.slice(2);
}

/** Terminate the process with `code`, matching `sys.exit(code)`. */
export function exitProcess(code) {
  process.exit(code);
}

