/**
 * Traceback rendering for an unhandled exception.
 *
 * The reference build is a PyInstaller bundle, so only the driver script's own
 * source lines are available to the traceback machinery; frames inside the
 * library print a location but no source. Frames are therefore described
 * declaratively here, with the same optional source/anchor lines CPython's
 * fine-grained error locations produce.
 */

import { writeStderr } from './sys.mjs';

/**
 * @typedef {object} Frame
 * @property {string} file     value for `File "..."`
 * @property {number} line     1-based line number
 * @property {string} func     enclosing function name, or `<module>`
 * @property {string} [source] source text, already stripped of indentation
 * @property {string} [anchor] `~`/`^` marker row aligned to `source`
 */

const INDENT = '    ';

/**
 * Print `Traceback (most recent call last): ...` followed by the exception.
 *
 * @param {Frame[]} frames outermost frame first, as CPython orders them
 * @param {{qualifiedName: string, displayMessage: () => string}} exc
 */
export function printTraceback(frames, exc) {
  let out = 'Traceback (most recent call last):\n';
  for (const frame of frames) {
    out += `  File "${frame.file}", line ${frame.line}, in ${frame.func}\n`;
    if (frame.source !== undefined) {
      out += `${INDENT}${frame.source}\n`;
      if (frame.anchor !== undefined) {
        out += `${INDENT}${frame.anchor}\n`;
      }
    }
  }
  const message = exc.displayMessage();
  out += message === '' ? `${exc.qualifiedName}\n` : `${exc.qualifiedName}: ${message}\n`;
  writeStderr(out);
}

