/**
 * argparse's internal control-flow exceptions.
 *
 * `ArgumentError` carries the offending action so the parser can prefix the
 * message with `argument <name>: `; `ParserExit` unwinds `-h` and fatal usage
 * errors up to the entry point instead of calling `process.exit()` deep inside
 * the parse.
 */

export class ArgumentError extends Error {
  /**
   * @param {string|null} argumentName pre-joined action name, or null
   * @param {string} message text after the `argument <name>: ` prefix
   */
  constructor(argumentName, message) {
    super(argumentName === null ? message : `argument ${argumentName}: ${message}`);
    this.argumentName = argumentName;
    this.rawMessage = message;
  }
}

/** Raised to stop parsing; `code` is the process exit status. */
export class ParserExit extends Error {
  constructor(code) {
    super(`parser exit ${code}`);
    this.code = code;
  }
}

