/**
 * Greedy word wrapping, matching `textwrap.wrap` for the whitespace-simple
 * strings argparse feeds it (option lists and one-line help text).
 */

/**
 * Wrap `text` so that no line exceeds `width` columns.
 *
 * Lines are filled greedily and a word longer than `width` is still emitted
 * alone rather than split, which is `textwrap`'s default (`break_long_words`
 * never triggers for the tokens argparse produces).
 *
 * @param {string} text whitespace-separated words
 * @param {number} width column budget for each line, including indents
 * @param {string} [initialIndent] prefix for the first line
 * @param {string} [subsequentIndent] prefix for every later line
 * @returns {string[]} wrapped lines, indents already applied
 */
export function wrapText(text, width, initialIndent = '', subsequentIndent = '') {
  const words = text.split(/\s+/).filter((word) => word.length > 0);
  if (words.length === 0) return [];

  const lines = [];
  let indent = initialIndent;
  let current = null;

  for (const word of words) {
    if (current === null) {
      current = indent + word;
      continue;
    }
    if (current.length + 1 + word.length > width) {
      lines.push(current);
      indent = subsequentIndent;
      current = indent + word;
    } else {
      current += ` ${word}`;
    }
  }
  if (current !== null) lines.push(current);
  return lines;
}

