/**
 * argparse's `HelpFormatter`, restricted to parsers built from optionals with
 * `store`/`help` actions — which is all `test19.py` uses.
 *
 * Layout constants follow argparse: the total width is the terminal width minus
 * two, the help column sits two spaces past the longest invocation but never
 * beyond `max_help_position`, and long usage lines wrap under the program name
 * only while the program name is short relative to the width.
 */

import { terminalColumns } from '../pyruntime/sys.mjs';
import { wrapText } from './text-wrap.mjs';

const PREFIX = 'usage: ';
const INDENT_INCREMENT = 2;

/** `[-h]` / `--k1 K1` — one usage token per action. */
function usagePart(action) {
  if (action.nargs === 0) {
    // Flags advertise only their first option string in the usage line.
    return action.required ? action.optionStrings[0] : `[${action.optionStrings[0]}]`;
  }
  const body = `${action.optionStrings[0]} ${action.metavar}`;
  return action.required ? body : `[${body}]`;
}

/** `-h, --help` / `--k1 K1` — the label in the options list. */
function helpInvocation(action) {
  if (action.nargs === 0) return action.optionStrings.join(', ');
  return action.optionStrings.map((opt) => `${opt} ${action.metavar}`).join(', ');
}

export class HelpFormatter {
  constructor(prog, actions) {
    this.prog = prog;
    this.actions = actions;
    this.width = Math.max(terminalColumns() - 2, 11);
  }

  /** The `usage: ...` block, without a trailing newline. */
  formatUsage() {
    const body = this.actions.map(usagePart).join(' ');
    const usage = `${this.prog} ${body}`;

    if (PREFIX.length + usage.length <= this.width) {
      return PREFIX + usage;
    }

    // Long usage: keep the program name on the first line when it leaves a
    // useful amount of room, otherwise give it a line of its own.
    if (PREFIX.length + this.prog.length <= 0.75 * this.width) {
      const indent = ' '.repeat(PREFIX.length + this.prog.length + 1);
      return wrapText(usage, this.width, PREFIX, indent).join('\n');
    }
    const indent = ' '.repeat(PREFIX.length);
    const lines = [PREFIX + this.prog];
    return lines.concat(wrapText(body, this.width, indent, indent)).join('\n');
  }

  /** Column at which help text starts, shared by every action. */
  #helpPosition() {
    let longest = 0;
    for (const action of this.actions) {
      longest = Math.max(longest, helpInvocation(action).length);
    }
    const actionMaxLength = longest + INDENT_INCREMENT;
    const maxHelpPosition = Math.min(
      24,
      Math.max(this.width - 20, INDENT_INCREMENT * 2),
    );
    return Math.min(actionMaxLength + 2, maxHelpPosition);
  }

  /** The full `--help` text, ending in exactly one newline. */
  formatHelp() {
    const helpPosition = this.#helpPosition();
    const helpWidth = Math.max(this.width - helpPosition, 11);
    const actionWidth = helpPosition - INDENT_INCREMENT - 2;
    const indent = ' '.repeat(INDENT_INCREMENT);

    let out = `${this.formatUsage()}\n\n options:\n`.replace(' options:', 'options:');
    for (const action of this.actions) {
      const invocation = helpInvocation(action);
      if (!action.help) {
        out += `${indent}${invocation}\n`;
        continue;
      }
      if (invocation.length <= actionWidth) {
        const header = indent + invocation.padEnd(actionWidth, ' ') + '  ';
        const lines = wrapText(
          action.help,
          this.width,
          header,
          ' '.repeat(helpPosition),
        );
        out += `${lines.join('\n')}\n`;
      } else {
        out += `${indent}${invocation}\n`;
        const lines = wrapText(
          action.help,
          helpPosition + helpWidth,
          ' '.repeat(helpPosition),
          ' '.repeat(helpPosition),
        );
        out += `${lines.join('\n')}\n`;
      }
    }
    return out;
  }
}

