 *
 * Covers the surface `test19.py` exercises and the surrounding behaviours a
 * caller can reach through it: `--opt=value`, prefix abbreviation with
 * ambiguity reporting, values that look like negative numbers, `--` as an
 * end-of-options marker, missing/duplicate/unknown arguments, `-h`, and the
 * two-line `usage:` + `prog: error:` diagnostic on stderr with status 2.
 */

import { writeStderr, writeStdout } from '../pyruntime/sys.mjs';
import { reprStr } from '../pyruntime/py-repr.mjs';
import { pyStr } from '../pyruntime/py-int.mjs';
import { ArgumentError, ParserExit } from './errors.mjs';
import { HelpFormatter } from './help-formatter.mjs';

/**
 * argparse's `_negative_number_matcher`. A token matching this is treated as a
 * value rather than an unknown option, provided no registered option string
 * could itself be mistaken for a negative number.
 */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

/** `_get_action_name` for an optional: every option string, slash-joined. */
function actionName(action) {
  return action.optionStrings.join('/');
}

export class ArgumentParser {
  /**
   * @param {{prog: string}} options `prog` is what usage/error lines are
   *   labelled with; argparse defaults it to `basename(sys.argv[0])`.
   */
  constructor({ prog }) {
    this.prog = prog;
    this.actions = [];
    // dest lookup and option-string lookup, both prototype-less so that user
    // input such as `--constructor` cannot collide with inherited properties.
    this.optionStringActions = Object.create(null);

    this.addArgument(['-h', '--help'], {
      dest: 'help',
      nargs: 0,
      help: 'show this help message and exit',
    });
  }

  /**
   * Register an optional argument.
   *
   * @param {string[]} optionStrings e.g. `['--k1']`
   * @param {object} [config] `dest`, `nargs` (0 for a flag), `type`,
   *   `required`, `metavar`, `help`
   */
  addArgument(optionStrings, config = {}) {
    const dest = config.dest ?? optionStrings[0].replace(/^-+/, '').replace(/-/g, '_');
    const action = {
      optionStrings,
      dest,
      nargs: config.nargs ?? 1,
      type: config.type ?? pyStr,
      required: config.required ?? false,
      metavar: config.metavar ?? dest.toUpperCase(),
      help: config.help ?? '',
    };
    this.actions.push(action);
    for (const optionString of optionStrings) {
      this.optionStringActions[optionString] = action;
    }
    return action;
  }

  #formatter() {
    return new HelpFormatter(this.prog, this.actions);
  }

  /** Print usage and the message to stderr, then exit 2. */
  error(message) {
    writeStderr(`${this.#formatter().formatUsage()}\n`);
    writeStderr(`${this.prog}: error: ${message}\n`);
    throw new ParserExit(2);
  }

  /** Print the help text to stdout, then exit 0. */
  printHelpAndExit() {
    writeStdout(this.#formatter().formatHelp());
    throw new ParserExit(0);
  }

