      // the leftovers, so it surfaces in `unrecognized arguments`.
      if (afterDoubleDash || token === '--') {
        afterDoubleDash = true;
        extras.push(token);
        i += 1;
        continue;
      }

      const optional = this.#parseOptional(token);
      if (optional === null || optional.action === null) {
        extras.push(token);
        i += 1;
        continue;
      }

      const { action, optionString, explicitArg } = optional;
      i += 1;

      if (action.nargs === 0) {
        if (explicitArg !== null) {
          throw new ArgumentError(
            actionName(action),
            `ignored explicit argument ${reprStr(explicitArg)}`,
          );
        }
        if (action.dest === 'help') this.printHelpAndExit();
        namespace[action.dest] = true;
        seen[action.dest] = true;
        continue;
      }

      let raw = explicitArg;
      if (raw === null) {
        const next = i < argStrings.length ? argStrings[i] : null;
        const nextIsValue = next !== null
          && next !== '--'
          && this.#parseOptional(next) === null;
        if (!nextIsValue) {
          throw new ArgumentError(actionName(action), 'expected one argument');
        }
        raw = next;
        i += 1;
      }

      namespace[action.dest] = this.#convert(action, optionString, raw);
      seen[action.dest] = true;
    }

    const missing = this.actions
      .filter((action) => action.required && seen[action.dest] !== true)
      .map(actionName);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return namespace;
  }
}

