/**
 * Insertion-ordered association store — the `dict` half of a bidict.
 *
 * Deliberately built on a prototype-less object index plus an entry array, so
 * lookups stay O(1) while iteration keeps Python's insertion order. Overwriting
 * an existing key updates the value *in place*, which is what makes
 * `b['new'] = 999` leave `'new'` in its original position.
 *
 * Keys are hashed to property names by the `encodeKey` function supplied at
 * construction, mirroring how Python relies on `__hash__`.
 */

export class OrderedStore {
  #index = Object.create(null);
  #entries = [];
  #liveCount = 0;
  #encodeKey;

  /**
   * @param {(key: unknown) => string} encodeKey injective key -> slot name
   */
  constructor(encodeKey) {
    this.#encodeKey = encodeKey;
  }

  get size() {
    return this.#liveCount;
  }

  has(key) {
    return this.#index[this.#encodeKey(key)] !== undefined;
  }

  /** The stored value, or `undefined` when absent. */
  get(key) {
    const entry = this.#index[this.#encodeKey(key)];
    return entry === undefined ? undefined : entry.value;
  }

  /** Insert at the end, or update in place if `key` is already present. */
  set(key, value) {
    const slot = this.#encodeKey(key);
    const existing = this.#index[slot];
    if (existing !== undefined) {
      existing.value = value;
      return;
    }
    const entry = { key, value, dead: false };
    this.#index[slot] = entry;
    this.#entries.push(entry);
    this.#liveCount += 1;
  }

  /** Remove `key` if present; returns whether anything was removed. */
  delete(key) {
    const slot = this.#encodeKey(key);
    const entry = this.#index[slot];
    if (entry === undefined) return false;
    entry.dead = true;
    delete this.#index[slot];
    this.#liveCount -= 1;
    this.#compactIfSparse();
    return true;
  }

  /** Live `[key, value]` pairs in insertion order. */
  items() {
    const out = [];
    for (const entry of this.#entries) {
      if (!entry.dead) out.push([entry.key, entry.value]);
    }
    return out;
  }

  /** A detached store with the same contents and order. */
  clone() {
    const copy = new OrderedStore(this.#encodeKey);
    for (const [key, value] of this.items()) copy.set(key, value);
    return copy;
  }

  /** Tombstones are cheap, but do not let them dominate the entry array. */
  #compactIfSparse() {
    if (this.#entries.length <= 8 || this.#liveCount * 2 > this.#entries.length) {
      return;
    }
    this.#entries = this.#entries.filter((entry) => !entry.dead);
  }
}

/** Slot encoder for Python `str` keys. */
export function encodeStrKey(key) {
  return `s${key}`;
}

/** Slot encoder for Python `int` keys, which this program models as bigint. */
export function encodeIntKey(key) {
  return `i${key.toString()}`;
}

