/**
 * bidict's duplication policies and the exceptions they raise.
 *
 * Policy semantics, as observable from the library's behaviour:
 *   RAISE     — reject the write
 *   DROP_OLD  — evict whatever already occupied the slot, then write
 *   DROP_NEW  — silently discard the incoming item
 */

import { PyException } from '../pyruntime/errors.mjs';
import { pyStrOf, PyTuple } from '../pyruntime/py-repr.mjs';

export const RAISE = 'RAISE';
export const DROP_OLD = 'DROP_OLD';
export const DROP_NEW = 'DROP_NEW';

/**
 * `bidict.ON_DUP_DEFAULT`: a repeated key quietly replaces its old value, while
 * a repeated value is an error, and an item that collides on both at once is
 * reported as its own distinct failure.
 */
export const ON_DUP_DEFAULT = { key: DROP_OLD, val: RAISE, kv: RAISE };

/**
 * Base for bidict's own exceptions.
 *
 * `str()` of a single-argument Python exception is `str()` of that argument,
 * so an int argument prints bare and a tuple argument prints as a tuple repr.
 * `dedupLine` records which line of `_dedup` raises, purely so the emulated
 * traceback can name it.
 */
class BidictException extends PyException {
  constructor(name, argument, dedupLine) {
    super(`bidict.${name}`, pyStrOf(argument));
    this.argument = argument;
    this.dedupLine = dedupLine;
  }
}

/** The incoming key already maps to a different value. */
export class KeyDuplicationError extends BidictException {
  constructor(key) {
    super('KeyDuplicationError', key, 340);
  }
}

/** The incoming value is already reached from a different key. */
export class ValueDuplicationError extends BidictException {
  constructor(value) {
    super('ValueDuplicationError', value, 347);
  }
}

/** Key and value each collide, with two *different* existing items. */
export class KeyAndValueDuplicationError extends BidictException {
  constructor(key, value) {
    super('KeyAndValueDuplicationError', new PyTuple([key, value]), 333);
  }
}

