/**
 * `bidict.bidict` — a mutable, order-preserving bidirectional mapping.
 *
 * Two independent insertion-ordered stores back every instance: forward
 * (key -> value) and inverse (value -> key). `inv` is not a copy but a second
 * facade over the *same* two stores with their roles swapped, so mutations are
 * visible through both and `b.inv.inv is b` holds. `copy()`, by contrast,
 * clones the stores, which is why writing to the original leaves the copy alone.
 */

import { PyKeyError } from '../pyruntime/errors.mjs';
import { pyRepr, reprDict } from '../pyruntime/py-repr.mjs';
import { OrderedStore, encodeIntKey, encodeStrKey } from './ordered-store.mjs';
import {
  DROP_NEW,
  DROP_OLD,
  KeyAndValueDuplicationError,
  KeyDuplicationError,
  ON_DUP_DEFAULT,
  RAISE,
  ValueDuplicationError,
} from './duplication.mjs';

/** Python `==` for the primitive key types this program uses. */
function pyEquals(left, right) {
  return left === right;
}

export class Bidict {
  /**
   * @param {Array<[unknown, unknown]>} [items] initial items, in order
   * @param {object} [stores] internal: pre-built stores to adopt instead
   */
  constructor(items = [], stores = null) {
    if (stores !== null) {
      this._fwd = stores.fwd;
      this._inv = stores.inv;
      this._inverse = stores.inverse ?? null;
      return;
    }
    this._fwd = new OrderedStore(encodeStrKey);
    this._inv = new OrderedStore(encodeIntKey);
    this._inverse = null;
    this.update(items);
  }

  /** The inverse mapping, sharing storage with this one. */
  get inv() {
    if (this._inverse === null) {
      const view = new Bidict([], { fwd: this._inv, inv: this._fwd, inverse: this });
      this._inverse = view;
    }
    return this._inverse;
  }

  get size() {
    return this._fwd.size;
  }

  /** `key in b` */
  has(key) {
    return this._fwd.has(key);
  }

  /** `b[key]`, raising `KeyError` when absent — as Python does. */
  getItem(key) {
    if (!this._fwd.has(key)) throw new PyKeyError(pyRepr(key));
    return this._fwd.get(key);
  }

  /** `b[key] = val` under the default duplication policy. */
  setItem(key, val) {
    this.put(key, val, ON_DUP_DEFAULT);
  }

  /** `b.put(key, val, on_dup)` — the explicit-policy form of `__setitem__`. */
  put(key, val, onDup = ON_DUP_DEFAULT) {
    const plan = this.#dedup(key, val, onDup);
    if (plan === null) return;
    this.#write(key, val, plan);
  }

  /** Apply `items` in order, as `bidict(...)` and `b.update(...)` do. */
  update(items) {
    for (const [key, val] of items) {
      this.put(key, val, ON_DUP_DEFAULT);
    }
  }

  /** A shallow copy whose stores are detached from this instance's. */
  copy() {
    return new Bidict([], { fwd: this._fwd.clone(), inv: this._inv.clone() });
  }

  /** `[key, value]` pairs in insertion order. */
  items() {
    return this._fwd.items();
  }

  /** `repr(b)` — `bidict({...})`. */
  toString() {
    return `bidict(${reprDict(this._fwd.items())})`;
  }

  /**
   * Decide what a write of `(key, val)` must displace, or reject it.
   *
   * @returns {null|{dropKey?: unknown, dropVal?: unknown}} `null` means the
   *   write is a no-op; otherwise the associations to evict first.
   */
  #dedup(key, val, onDup) {
    const isDupKey = this._fwd.has(key);
    const isDupVal = this._inv.has(val);

    if (isDupKey && isDupVal) {
      const oldKey = this._inv.get(val);
      // Re-inserting an item that is already present changes nothing, so it is
