/**
 * Python `dict` literal evaluation.
 *
 * `{k1: v1, k2: v2}` is not simply a pair list: when the two key expressions
 * evaluate equal, the literal collapses to one entry that keeps the *first*
 * key's position and the *last* value. `bidict({args.k1: ..., args.k2: ...})`
 * therefore never sees a duplicate key, only a possibly shorter dict.
 */

import { OrderedStore, encodeStrKey } from '../bidict/ordered-store.mjs';

/**
 * Evaluate a `dict` display with `str` keys.
 *
 * @param {Array<[string, unknown]>} pairs key/value expressions, in source order
 * @returns {Array<[string, unknown]>} resulting items, in insertion order
 */
export function dictLiteral(pairs) {
  const store = new OrderedStore(encodeStrKey);
  for (const [key, value] of pairs) {
    store.set(key, value);
  }
  return store.items();
}

