/**
 * Traceback rendering for an unhandled exception.
 *
 * Frames are described declaratively because the reference is a PyInstaller
 * bundle: only the driver script's own file is ever on disk, so library frames
 * print a location and nothing else.
 *
 * The driver's frames behave the same way. `linecache` resolves the recorded
 * filename — a bare `test19.py` — against the *current working directory*, so
 * the source echo and its `~`/`^` marker appear only when a matching file
 * happens to sit there. That is reproduced here rather than hard-coded, so the
 * output tracks the reference from any directory.
 */

import { readFileSync } from 'node:fs';
import { writeStderr } from './sys.mjs';

/**
 * @typedef {object} Frame
 * @property {string} file     value for `File "..."`, resolved like linecache
 * @property {number} line     1-based line number
 * @property {string} func     enclosing function name, or `<module>`
 * @property {string} [anchor] `~`/`^` marker row, aligned to the source text
 */

const INDENT = '    ';

/** The frame's source line with indentation stripped, or null if unavailable. */
function lookupLine(file, lineNumber) {
  let text;
  try {
    text = readFileSync(file, 'utf8');
  } catch {
    return null;
  }
  const lines = text.split('\n');
  if (lineNumber < 1 || lineNumber > lines.length) return null;
  const line = lines[lineNumber - 1].trim();
  return line === '' ? null : line;
}

/**
 * Print `Traceback (most recent call last): ...` followed by the exception.
 *
 * @param {Frame[]} frames outermost frame first, as CPython orders them
 * @param {{qualifiedName: string, displayMessage: () => string}} exc
 */
export function printTraceback(frames, exc) {
  let out = 'Traceback (most recent call last):\n';
  for (const frame of frames) {
    out += `  File "${frame.file}", line ${frame.line}, in ${frame.func}\n`;
    const source = lookupLine(frame.file, frame.line);
    if (source !== null) {
      out += `${INDENT}${source}\n`;
      if (frame.anchor !== undefined) out += `${INDENT}${frame.anchor}\n`;
    }
  }
  const message = exc.displayMessage();
  out += message === '' ? `${exc.qualifiedName}\n` : `${exc.qualifiedName}: ${message}\n`;
  writeStderr(out);
}

