#!/usr/bin/env node
/**
 * Node.js port of /workspace/dataset/test19.py — bidict copy semantics.
 *
 * The Python original:
 *   1. parses four required options (`--k1 --v1 --k2 --v2`) with argparse,
 *   2. builds `bidict({k1: v1, k2: v2})` and copies it,
 *   3. mutates the original with `b1['new'] = 999` to show the copy is detached,
 *   4. reads `b2.inv[v1]` back through the copy's inverse.
 *
 * Every observable behaviour is reproduced, including the failure modes: a
 * duplicated value aborts step 2 or 3 with a bidict duplication error, and
 * `k1 == k2` makes step 4 raise `KeyError` *after* the three lines of output
 * have already been printed. Those paths print a Python traceback to stderr and
 * exit 1; argparse usage errors print to stderr and exit 2.
 */

import { ArgumentParser, ParserExit } from './lib/argparse/index.mjs';
import { Bidict } from './lib/bidict/index.mjs';
import { dictLiteral } from './lib/pyruntime/py-dict.mjs';
import { isPyException } from './lib/pyruntime/errors.mjs';
import { pyInt } from './lib/pyruntime/py-int.mjs';
import { argvTail, exitProcess, print } from './lib/pyruntime/sys.mjs';
import { printTraceback } from './lib/pyruntime/traceback.mjs';

/**
 * `prog` for usage and error output.
 *
 * argparse derives this from `basename(sys.argv[0])`. The reference build is
 * `test19_executable`, so that name is pinned here to keep `--help` — the one
 * diagnostic stream that is byte-comparable — identical to the original.
 */
const PROG = 'test19_executable';

/** Source locations for the traceback, keyed by the statement that can fail. */
const FRAMES = {
  construct: [
    {
      file: 'test19.py',
      line: 12,
      func: '<module>',
      source: 'b1 = bidict({args.k1: args.v1, args.k2: args.v2})',
      anchor: '     ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^',
    },
    { file: 'bidict/_base.py', line: 161, func: '__init__' },
    { file: 'bidict/_base.py', line: 454, func: '_update' },
  ],
  setItem: [
    {
      file: 'test19.py',
      line: 17,
      func: '<module>',
      source: "b1['new'] = 999",
      anchor: '~~^^^^^^^',
    },
    { file: 'bidict/_bidict.py', line: 80, func: '__setitem__' },
    { file: 'bidict/_bidict.py', line: 106, func: 'put' },
    { file: 'bidict/_base.py', line: 454, func: '_update' },
  ],
  inverseLookup: [
    {
      file: 'test19.py',
      line: 22,
      func: '<module>',
      source: 'result = b2.inv[args.v1]',
      anchor: '         ~~~~~~^^^^^^^^^',
    },
    { file: 'bidict/_base.py', line: 524, func: '__getitem__' },
  ],
};

function buildParser() {
  const parser = new ArgumentParser({ prog: PROG });
  parser.addArgument(['--k1'], { required: true });
  parser.addArgument(['--v1'], { type: pyInt, required: true });
  parser.addArgument(['--k2'], { required: true });
  parser.addArgument(['--v2'], { type: pyInt, required: true });
  return parser;
}

/**
 * Run `body`, and on a Python-level exception print the traceback that CPython
 * would emit from `frames` and exit 1.
 *
 * `_dedup` raises from a different line per duplication kind, so the innermost
 * frame's line number comes from the exception itself.
 */
function guard(frames, body) {
  try {
    return body();
  } catch (err) {
    if (!isPyException(err)) throw err;
    const trace = err.dedupLine === undefined
      ? frames
      : frames.concat([{ file: 'bidict/_base.py', line: err.dedupLine, func: '_dedup' }]);
    printTraceback(trace, err);
    exitProcess(1);
    return undefined;
  }
}

function main() {
  const parser = buildParser();
  const args = parser.parseArgs(argvTail());

  // 复制bidict
  const b1 = guard(
    FRAMES.construct,
    () => new Bidict(dictLiteral([[args.k1, args.v1], [args.k2, args.v2]])),
  );
  const b2 = b1.copy();
  print(b2.toString());

  // 修改原字典不影响副本
  guard(FRAMES.setItem, () => b1.setItem('new', 999n));
  print(b1.toString());
  print(b2.toString());

  // 副本的反转操作
  const result = guard(FRAMES.inverseLookup, () => b2.inv.getItem(args.v1));
  print(result);
}

try {
  main();
} catch (err) {
  if (err instanceof ParserExit) {
    exitProcess(err.code);
  }
  throw err;
}

