#!/usr/bin/env node
/**
 * Randomised differential fuzz: generate argument vectors that mix ordinary
 * inputs with the collision-prone values (999, repeated keys, repeated values)
 * and compare the reference build against the Node port.
 */

import { spawnSync } from 'node:child_process';

const REF = '/workspace/dataset/test19_executable';
const PORT = '/output/test19.mjs';
const ROUNDS = Number(process.argv[2] ?? 400);

const KEYS = [
  'a', 'b', 'new', '', 'e', 's', "q'r", 'x"y', 'a\nb', 'a\tb', 'a\\b',
  '中文', '\u{1F600}', '-5', '-', 'a b', '__proto__', 'k1',
];
const VALUES = [
  '0', '1', '5', '7', '23', '999', '-999', '-5', '007', '1_0', '5.0', 'x',
  '', '  42  ', '٣', '１２', '99999999999999999999', '+7',
];

function pick(list) {
  return list[Math.floor(Math.random() * list.length)];
}

function stripPyiLine(text) {
  return text.replace(/^\[PYI-\d+:ERROR\].*\n?/gm, '');
}

function run(cmd, argv, args) {
  const res = spawnSync(cmd, argv.concat(args), { encoding: 'utf8' });
  return {
    stdout: res.stdout ?? '',
    stderr: stripPyiLine(res.stderr ?? ''),
    status: res.status,
  };
}

/** Build one argument vector, occasionally dropping or duplicating a flag. */
function makeArgs() {
  const flags = [
    ['--k1', pick(KEYS)],
    ['--v1', pick(VALUES)],
    ['--k2', pick(KEYS)],
    ['--v2', pick(VALUES)],
  ];
  const out = [];
  for (const [flag, value] of flags) {
    const roll = Math.random();
    if (roll < 0.05) continue;                       // omit a required flag
    if (roll < 0.20) out.push(`${flag}=${value}`);   // inline form
    else out.push(flag, value);
  }
  if (Math.random() < 0.05) out.push('--');
  if (Math.random() < 0.05) out.push('stray');
  if (Math.random() < 0.05) out.unshift('--k');
  return out;
}

let failed = 0;
for (let round = 0; round < ROUNDS; round += 1) {
  const args = makeArgs();
  const ref = run(REF, [], args);
  const got = run(process.execPath, [PORT], args);
  if (ref.stdout !== got.stdout || ref.stderr !== got.stderr || ref.status !== got.status) {
    failed += 1;
    console.log('MISMATCH', JSON.stringify(args));
    console.log('  ref', JSON.stringify(ref));
    console.log('  got', JSON.stringify(got));
    if (failed > 5) break;
  }
}

console.log(`${ROUNDS - failed}/${ROUNDS} random vectors matched`);
process.exit(failed === 0 ? 0 : 1);

