/**
 * Insertion-ordered association store — the `dict` half of a bidict.
 *
 * Deliberately built on a prototype-less object index plus an entry array, so
 * lookups stay O(1) while iteration keeps Python's insertion order. Overwriting
 * an existing key updates the value *in place*, which is what makes
 * `b['new'] = 999` leave `'new'` in its original position.
 *
 * Keys are hashed to property names by the `encodeKey` function supplied at
 * construction, mirroring how Python relies on `__hash__`.
 */

export class OrderedStore {
  #index = Object.create(null);
  #entries = [];
  #liveCount = 0;
  #encodeKey;

  /**
   * @param {(key: unknown) => string} encodeKey injective key -> slot name
   */
  constructor(encodeKey) {
    this.#encodeKey = encodeKey;
  }

  get size() {
    return this.#liveCount;
  }

  has(key) {
    return this.#index[this.#encodeKey(key)] !== undefined;
  }

  /** The stored value, or `undefined` when absent. */
  get(key) {
    const entry = this.#index[this.#encodeKey(key)];
    return entry === undefined ? undefined : entry.value;
  }

  /** Insert at the end, or update in place if `key` is already present. */
  set(key, value) {
    const slot = this.#encodeKey(key);
    const existing = this.#index[slot];
    if (existing !== undefined) {
      existing.value = value;
      return;
    }
    const entry = { key, value, dead: false };
    this.#index[slot] = entry;
    this.#entries.push(entry);
    this.#liveCount += 1;
  }

  /** Remove `key` if present; returns whether anything was removed. */
  delete(key) {
    const slot = this.#encodeKey(key);
    const entry = this.#index[slot];
    if (entry === undefined) return false;
    entry.dead = true;
    delete this.#index[slot];
    this.#liveCount -= 1;
    this.#compactIfSparse();
    return true;
  }

  /** Live `[key, value]` pairs in insertion order. */
  items() {
    const out = [];
    for (const entry of this.#entries) {
      if (!entry.dead) out.push([entry.key, entry.value]);
    }
    return out;
  }

  /** A detached store with the same contents and order. */
  clone() {
    const copy = new OrderedStore(this.#encodeKey);
    for (const [key, value] of this.items()) copy.set(key, value);
    return copy;
  }

  /** Tombstones are cheap, but do not let them dominate the entry array. */
  #compactIfSparse() {
    if (this.#entries.length <= 8 || this.#liveCount * 2 > this.#entries.length) {
      return;
    }
    this.#entries = this.#entries.filter((entry) => !entry.dead);
  }
}

/** Slot encoder for Python `str` keys. */
export function encodeStrKey(key) {
  return `s${key}`;
}

/** Slot encoder for Python `int` keys, which this program models as bigint. */
export function encodeIntKey(key) {
  return `i${key.toString()}`;
}

/**
 * Python `dict` literal evaluation.
 *
 * `{k1: v1, k2: v2}` is not simply a pair list: when the two key expressions
 * evaluate equal, the literal collapses to one entry that keeps the *first*
 * key's position and the *last* value. `bidict({args.k1: ..., args.k2: ...})`
 * therefore never sees a duplicate key, only a possibly shorter dict.
 */

import { OrderedStore, encodeStrKey } from '../bidict/ordered-store.mjs';

/**
 * Evaluate a `dict` display with `str` keys.
 *
 * @param {Array<[string, unknown]>} pairs key/value expressions, in source order
 * @returns {Array<[string, unknown]>} resulting items, in insertion order
 */
export function dictLiteral(pairs) {
  const store = new OrderedStore(encodeStrKey);
  for (const [key, value] of pairs) {
    store.set(key, value);
  }
  return store.items();
}

/**
 * `bidict.bidict` — a mutable, order-preserving bidirectional mapping.
 *
 * Two independent insertion-ordered stores back every instance: forward
 * (key -> value) and inverse (value -> key). `inv` is not a copy but a second
 * facade over the *same* two stores with their roles swapped, so mutations are
 * visible through both and `b.inv.inv is b` holds. `copy()`, by contrast,
 * clones the stores, which is why writing to the original leaves the copy alone.
 */

import { PyKeyError } from '../pyruntime/errors.mjs';
import { pyRepr, reprDict } from '../pyruntime/py-repr.mjs';
import { OrderedStore, encodeIntKey, encodeStrKey } from './ordered-store.mjs';
import {
  DROP_NEW,
  KeyAndValueDuplicationError,
  KeyDuplicationError,
  ON_DUP_DEFAULT,
  RAISE,
  ValueDuplicationError,
} from './duplication.mjs';

/** Python `==` for the primitive key types this program uses. */
function pyEquals(left, right) {
  return left === right;
}

export class Bidict {
  /**
   * @param {Array<[unknown, unknown]>} [items] initial items, in order
   * @param {object} [stores] internal: pre-built stores to adopt instead
   */
  constructor(items = [], stores = null) {
    if (stores !== null) {
      this._fwd = stores.fwd;
      this._inv = stores.inv;
      this._inverse = stores.inverse ?? null;
      return;
    }
    this._fwd = new OrderedStore(encodeStrKey);
    this._inv = new OrderedStore(encodeIntKey);
    this._inverse = null;
    this.update(items);
  }

  /** The inverse mapping, sharing storage with this one. */
  get inv() {
    if (this._inverse === null) {
      const view = new Bidict([], { fwd: this._inv, inv: this._fwd, inverse: this });
      this._inverse = view;
    }
    return this._inverse;
  }

  get size() {
    return this._fwd.size;
  }

  /** `key in b` */
  has(key) {
    return this._fwd.has(key);
  }

  /** `b[key]`, raising `KeyError` when absent — as Python does. */
  getItem(key) {
    if (!this._fwd.has(key)) throw new PyKeyError(pyRepr(key));
    return this._fwd.get(key);
  }

  /** `b[key] = val` under the default duplication policy. */
  setItem(key, val) {
    this.put(key, val, ON_DUP_DEFAULT);
  }

  /** `b.put(key, val, on_dup)` — the explicit-policy form of `__setitem__`. */
  put(key, val, onDup = ON_DUP_DEFAULT) {
    const plan = this.#dedup(key, val, onDup);
    if (plan === null) return;
    this.#write(key, val, plan);
  }

  /** Apply `items` in order, as `bidict(...)` and `b.update(...)` do. */
  update(items) {
    for (const [key, val] of items) {
      this.put(key, val, ON_DUP_DEFAULT);
    }
  }

  /** A shallow copy whose stores are detached from this instance's. */
  copy() {
    return new Bidict([], { fwd: this._fwd.clone(), inv: this._inv.clone() });
  }

  /** `[key, value]` pairs in insertion order. */
  items() {
    return this._fwd.items();
  }

  /** `repr(b)` — `bidict({...})`. */
  toString() {
    return `bidict(${reprDict(this._fwd.items())})`;
  }

  /**
   * Decide what a write of `(key, val)` must displace, or reject it.
   *
   * @returns {null|{dropKey?: unknown, dropVal?: unknown}} `null` means the
   *   write is a no-op; otherwise the associations to evict first.
   */
  #dedup(key, val, onDup) {
    const isDupKey = this._fwd.has(key);
    const isDupVal = this._inv.has(val);

    if (isDupKey && isDupVal) {
      const oldKey = this._inv.get(val);
      // Re-inserting an item that is already present changes nothing, so it is
      // not a duplication error.
      if (pyEquals(oldKey, key)) return null;
      if (onDup.kv === RAISE) throw new KeyAndValueDuplicationError(key, val);
      if (onDup.kv === DROP_NEW) return null;
      return { dropVal: this._fwd.get(key), dropKey: oldKey };
    }

    if (isDupKey) {
      if (onDup.key === RAISE) throw new KeyDuplicationError(key);
      if (onDup.key === DROP_NEW) return null;
      return { dropVal: this._fwd.get(key) };
    }

    if (isDupVal) {
      if (onDup.val === RAISE) throw new ValueDuplicationError(val);
      if (onDup.val === DROP_NEW) return null;
      return { dropKey: this._inv.get(val) };
    }

    return {};
  }

  #write(key, val, plan) {
    if (plan.dropVal !== undefined) this._inv.delete(plan.dropVal);
    if (plan.dropKey !== undefined) this._fwd.delete(plan.dropKey);
    // set() updates in place for an existing key, preserving its position.
    this._fwd.set(key, val);
    this._inv.set(val, key);
  }
}

