/** Public surface of the bidict emulation. */

export { Bidict } from './bidict.mjs';
export {
  DROP_NEW,
  DROP_OLD,
  KeyAndValueDuplicationError,
  KeyDuplicationError,
  ON_DUP_DEFAULT,
  RAISE,
  ValueDuplicationError,
} from './duplication.mjs';
export { OrderedStore, encodeIntKey, encodeStrKey } from './ordered-store.mjs';

/**
 * CPython's `int(str)` conversion, base 10.
 *
 * Reproduces the two-stage behaviour of the real conversion:
 *   1. `_PyUnicode_TransformDecimalAndSpaceToASCII` folds non-ASCII Unicode
 *      spaces to U+0020 and non-ASCII decimal digits to ASCII digits, then
 *   2. the C scanner skips `Py_ISSPACE` (ASCII-only) padding, reads one
 *      optional sign, and reads digits with PEP 515 underscore separators.
 *
 * That split is why `int(' 5')` is 5 while `int('5')` raises, even
 * though `''.isspace()` is true.
 */

import { PyValueError } from './errors.mjs';
import {
  decimalDigitValue,
  isAsciiSpace,
  isTransformedSpace,
} from './unicode-data.mjs';
import { reprStr } from './py-repr.mjs';

/** Stage 1: fold non-ASCII spaces and digits into their ASCII equivalents. */
function transformDecimalAndSpaceToAscii(text) {
  let out = '';
  for (const ch of text) {
    const cp = ch.codePointAt(0);
    if (cp <= 0x7f) {
      out += ch;
      continue;
    }
    if (isTransformedSpace(cp)) {
      out += ' ';
      continue;
    }
    const digit = decimalDigitValue(cp);
    // Anything that is neither space nor digit is replaced by a placeholder
    // that cannot parse, exactly as CPython does.
    out += digit >= 0 ? String(digit) : '?';
  }
  return out;
}

function isAsciiDigit(ch) {
  return ch >= '0' && ch <= '9';
}

/**
 * Convert `text` to a Python integer.
 *
 * @param {string} text raw command-line token
 * @returns {bigint} arbitrary-precision result, matching Python's unbounded int
 * @throws {PyValueError} with CPython's own message on malformed input
 */
export function pyInt(text) {
  const invalid = () => new PyValueError(
    `invalid literal for int() with base 10: ${reprStr(text)}`,
  );

  const scanned = transformDecimalAndSpaceToAscii(text);

  let start = 0;
  let end = scanned.length;
  while (start < end && isAsciiSpace(scanned.charCodeAt(start))) start += 1;
  while (end > start && isAsciiSpace(scanned.charCodeAt(end - 1))) end -= 1;

  let i = start;
  let negative = false;
  if (i < end && (scanned[i] === '+' || scanned[i] === '-')) {
    negative = scanned[i] === '-';
    i += 1;
  }

  let digits = '';
  let previousWasUnderscore = false;
  for (; i < end; i += 1) {
    const ch = scanned[i];
    if (ch === '_') {
      // An underscore is only legal between two digits.
      if (previousWasUnderscore || digits.length === 0) throw invalid();
      previousWasUnderscore = true;
      continue;
    }
    if (!isAsciiDigit(ch)) throw invalid();
    digits += ch;
    previousWasUnderscore = false;
  }

  if (digits.length === 0 || previousWasUnderscore) throw invalid();

  const magnitude = BigInt(digits);
  return negative ? -magnitude : magnitude;
}

/** `int.__name__`, used by argparse when it reports a conversion failure. */
pyInt.pyName = 'int';

/** Python's `str` conversion — argparse's default `type`. */
export function pyStr(text) {
  return text;
}

pyStr.pyName = 'str';

