#!/usr/bin/env node
/**
 * Node.js port of /workspace/dataset/test19.py — bidict copy semantics.
 *
 * The Python original:
 *   1. parses four required options (`--k1 --v1 --k2 --v2`) with argparse,
 *   2. builds `bidict({k1: v1, k2: v2})` and copies it,
 *   3. mutates the original with `b1['new'] = 999` to show the copy is detached,
 *   4. reads `b2.inv[v1]` back through the copy's inverse.
 *
 * Every observable behaviour is reproduced, including the failure modes: a
 * duplicated value aborts step 2 or 3 with a bidict duplication error, and
 * `k1 == k2` makes step 4 raise `KeyError` *after* the three lines of output
 * have already been printed. Those paths print a Python traceback to stderr and
 * exit 1; argparse usage errors print to stderr and exit 2.
 */

import { ArgumentParser, ParserExit } from './lib/argparse/index.mjs';
import { Bidict } from './lib/bidict/index.mjs';
import { dictLiteral } from './lib/pyruntime/py-dict.mjs';
import { isPyException } from './lib/pyruntime/errors.mjs';
import { pyInt } from './lib/pyruntime/py-int.mjs';
import { argvTail, exitProcess, print } from './lib/pyruntime/sys.mjs';
import { printTraceback } from './lib/pyruntime/traceback.mjs';

/**
 * `prog` for usage and error output.
 *
 * argparse derives this from `basename(sys.argv[0])`. The reference build is
 * `test19_executable`, so that name is pinned here to keep `--help` — the one
 * diagnostic stream that is byte-comparable — identical to the original.
 */
const PROG = 'test19_executable';

/**
 * Source locations for the traceback, keyed by the statement that can fail.
 *
 * Only the `~`/`^` marker is recorded: the source echo itself is read back from
 * `test19.py` at print time, exactly as CPython's `linecache` does.
 */
const FRAMES = {
  construct: [
    {
      file: 'test19.py',
      line: 12,
      func: '<module>',
      anchor: '     ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^',
    },
    { file: 'bidict/_base.py', line: 161, func: '__init__' },
    { file: 'bidict/_base.py', line: 454, func: '_update' },
  ],
  setItem: [
    {
      file: 'test19.py',
      line: 17,
      func: '<module>',
      anchor: '~~^^^^^^^',
    },
    { file: 'bidict/_bidict.py', line: 80, func: '__setitem__' },
    { file: 'bidict/_bidict.py', line: 106, func: 'put' },
    { file: 'bidict/_base.py', line: 454, func: '_update' },
  ],
  inverseLookup: [
    {
      file: 'test19.py',
      line: 22,
      func: '<module>',
      anchor: '         ~~~~~~^^^^^^^^^',
    },
    { file: 'bidict/_base.py', line: 524, func: '__getitem__' },
  ],
};

function buildParser() {
  const parser = new ArgumentParser({ prog: PROG });
  parser.addArgument(['--k1'], { required: true });
  parser.addArgument(['--v1'], { type: pyInt, required: true });
  parser.addArgument(['--k2'], { required: true });
  parser.addArgument(['--v2'], { type: pyInt, required: true });
  return parser;
}

/**
 * Run `body`, and on a Python-level exception print the traceback that CPython
 * would emit from `frames` and exit 1.
 *
 * `_dedup` raises from a different line per duplication kind, so the innermost
 * frame's line number comes from the exception itself.
 */
function guard(frames, body) {
  try {
    return body();
  } catch (err) {
    if (!isPyException(err)) throw err;
    const trace = err.dedupLine === undefined
      ? frames
      : frames.concat([{ file: 'bidict/_base.py', line: err.dedupLine, func: '_dedup' }]);
    printTraceback(trace, err);
    exitProcess(1);
    return undefined;
  }
}

function main() {
  const parser = buildParser();
  const args = parser.parseArgs(argvTail());

  // 复制bidict
  const b1 = guard(
    FRAMES.construct,
    () => new Bidict(dictLiteral([[args.k1, args.v1], [args.k2, args.v2]])),
  );
  const b2 = b1.copy();
  print(b2.toString());

  // 修改原字典不影响副本
  guard(FRAMES.setItem, () => b1.setItem('new', 999n));
  print(b1.toString());
  print(b2.toString());

  // 副本的反转操作
  const result = guard(FRAMES.inverseLookup, () => b2.inv.getItem(args.v1));
  print(result);
}

try {
  main();
} catch (err) {
  if (err instanceof ParserExit) {
    exitProcess(err.code);
  }
  throw err;
}

/**
 * A focused re-implementation of `argparse.ArgumentParser`.
 *
 * Covers the surface `test19.py` exercises and the surrounding behaviours a
 * caller can reach through it: `--opt=value`, prefix abbreviation with
 * ambiguity reporting, values that look like negative numbers, `--` as an
 * end-of-options marker, missing/duplicate/unknown arguments, `-h`, and the
 * two-line `usage:` + `prog: error:` diagnostic on stderr with status 2.
 */

import { writeStderr, writeStdout } from '../pyruntime/sys.mjs';
import { reprStr } from '../pyruntime/py-repr.mjs';
import { pyStr } from '../pyruntime/py-int.mjs';
import { ArgumentError, ParserExit } from './errors.mjs';
import { HelpFormatter } from './help-formatter.mjs';

/**
 * argparse's `_negative_number_matcher`. A token matching this is treated as a
 * value rather than an unknown option, provided no registered option string
 * could itself be mistaken for a negative number.
 */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

/** `_get_action_name` for an optional: every option string, slash-joined. */
function actionName(action) {
  return action.optionStrings.join('/');
}

export class ArgumentParser {
  /**
   * @param {{prog: string}} options `prog` is what usage/error lines are
   *   labelled with; argparse defaults it to `basename(sys.argv[0])`.
   */
  constructor({ prog }) {
    this.prog = prog;
    this.actions = [];
    // dest lookup and option-string lookup, both prototype-less so that user
    // input such as `--constructor` cannot collide with inherited properties.
    this.optionStringActions = Object.create(null);

    this.addArgument(['-h', '--help'], {
      dest: 'help',
      nargs: 0,
      help: 'show this help message and exit',
    });
  }

  /**
   * Register an optional argument.
   *
   * @param {string[]} optionStrings e.g. `['--k1']`
   * @param {object} [config] `dest`, `nargs` (0 for a flag), `type`,
   *   `required`, `metavar`, `help`
   */
  addArgument(optionStrings, config = {}) {
    const dest = config.dest ?? optionStrings[0].replace(/^-+/, '').replace(/-/g, '_');
    const action = {
      optionStrings,
      dest,
      nargs: config.nargs ?? 1,
      type: config.type ?? pyStr,
      required: config.required ?? false,
      metavar: config.metavar ?? dest.toUpperCase(),
      help: config.help ?? '',
    };
    this.actions.push(action);
    for (const optionString of optionStrings) {
      this.optionStringActions[optionString] = action;
    }
    return action;
  }

  #formatter() {
    return new HelpFormatter(this.prog, this.actions);
  }

  /** Print usage and the message to stderr, then exit 2. */
  error(message) {
    writeStderr(`${this.#formatter().formatUsage()}\n`);
    writeStderr(`${this.prog}: error: ${message}\n`);
    throw new ParserExit(2);
  }

  /** Print the help text to stdout, then exit 0. */
  printHelpAndExit() {
    writeStdout(this.#formatter().formatHelp());
    throw new ParserExit(0);
  }

  /** Every registered option string that begins with `prefix`, in order. */
  #optionTuples(argString) {
    const result = [];
    if (argString.startsWith('--')) {
      const eq = argString.indexOf('=');
      const optionPrefix = eq === -1 ? argString : argString.slice(0, eq);
      const explicitArg = eq === -1 ? null : argString.slice(eq + 1);
      for (const optionString of Object.keys(this.optionStringActions)) {
        if (optionString.startsWith(optionPrefix)) {
          result.push({
            action: this.optionStringActions[optionString],
            optionString,
            explicitArg,
          });
        }
      }
      return result;
    }
    // Single dash: either an abbreviation of a long-ish short option, or a
    // short option with its value glued on (`-hVALUE`).
    const shortOptionPrefix = argString.slice(0, 2);
    const shortExplicitArg = argString.slice(2);
    for (const optionString of Object.keys(this.optionStringActions)) {
      if (optionString === shortOptionPrefix) {
        result.push({
          action: this.optionStringActions[optionString],
          optionString,
          explicitArg: shortExplicitArg === '' ? null : shortExplicitArg,
        });
      } else if (optionString.startsWith(argString)) {
        result.push({
          action: this.optionStringActions[optionString],
          optionString,
          explicitArg: null,
        });
      }
    }
    return result;
  }

  /**
   * Classify one token.
   *
   * @returns {null|{action: object|null, optionString: string, explicitArg: string|null}}
   *   `null` means "this is a value". A result with `action === null` means
   *   "this looks like an option but no such option exists".
   */
  #parseOptional(argString) {
    if (argString.length === 0) return null;
    if (!argString.startsWith('-')) return null;

    const exact = this.optionStringActions[argString];
    if (exact !== undefined) {
      return { action: exact, optionString: argString, explicitArg: null };
    }
    // A lone '-' was meant positionally.
    if (argString.length === 1) return null;

    const eq = argString.indexOf('=');
    if (eq !== -1) {
      const optionString = argString.slice(0, eq);
      const known = this.optionStringActions[optionString];
      if (known !== undefined) {
        return { action: known, optionString, explicitArg: argString.slice(eq + 1) };
      }
    }

    const tuples = this.#optionTuples(argString);
    if (tuples.length > 1) {
      const options = tuples.map((tuple) => tuple.optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${options}`);
    }
    if (tuples.length === 1) return tuples[0];

    // No option string here looks like a negative number, so `-5` and `-.5`
    // are values rather than typos.
    if (NEGATIVE_NUMBER.test(argString)) return null;
    if (argString.includes(' ')) return null;

    return { action: null, optionString: argString, explicitArg: null };
  }

  #convert(action, raw) {
    try {
      return action.type(raw);
    } catch {
      const typeName = action.type.pyName ?? action.type.name;
      throw new ArgumentError(
        actionName(action),
        `invalid ${typeName} value: ${reprStr(raw)}`,
      );
    }
  }

  /**
   * Parse `argStrings`, exiting on `-h` or on any usage error.
   *
   * @param {string[]} argStrings tokens after the program name
   * @returns {object} namespace keyed by each action's `dest`
   */
  parseArgs(argStrings) {
    try {
      return this.#parseKnownArgs(argStrings);
    } catch (err) {
      // argparse funnels every ArgumentError through error(), which prints
      // usage and exits 2.
      if (err instanceof ArgumentError) this.error(err.message);
      throw err;
    }
  }

  #parseKnownArgs(argStrings) {
    const namespace = Object.create(null);
    const seen = Object.create(null);
    const extras = [];
    let afterDoubleDash = false;

    let i = 0;
    while (i < argStrings.length) {
      const token = argStrings[i];

      // `--` terminates option parsing. argparse keeps the marker itself among
      // the leftovers, so it surfaces in `unrecognized arguments`.
      if (afterDoubleDash || token === '--') {
        afterDoubleDash = true;
        extras.push(token);
        i += 1;
        continue;
      }

      const optional = this.#parseOptional(token);
      if (optional === null || optional.action === null) {
        extras.push(token);
        i += 1;
        continue;
      }

      const { action, explicitArg } = optional;
      i += 1;

      if (action.nargs === 0) {
        if (explicitArg !== null) {
          throw new ArgumentError(
            actionName(action),
            `ignored explicit argument ${reprStr(explicitArg)}`,
          );
        }
        if (action.dest === 'help') this.printHelpAndExit();
        namespace[action.dest] = true;
        seen[action.dest] = true;
        continue;
      }

      let raw = explicitArg;
      if (raw === null) {
        const next = i < argStrings.length ? argStrings[i] : null;
        const nextIsValue = next !== null
          && next !== '--'
          && this.#parseOptional(next) === null;
        if (!nextIsValue) {
          throw new ArgumentError(actionName(action), 'expected one argument');
        }
        raw = next;
        i += 1;
      }

      namespace[action.dest] = this.#convert(action, raw);
      seen[action.dest] = true;
    }

    const missing = this.actions
      .filter((action) => action.required && seen[action.dest] !== true)
      .map(actionName);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return namespace;
  }
}
